   "id": "z969b9c7c",
   "sez": "mondo",
   "titolo": "Allarme bomba su un volo Wizz Air, atterraggio di emergenza a Budapest",
   "orig": "Wizz Air flight from Luton in emergency landing after bomb threat",
   "lead": "Un volo della compagnia Wizz Air partito dall'aeroporto di Luton, a Londra, è stato costretto a un atterraggio di emergenza a causa di un allarme bomba ricevuto mentre l'aereo si trovava in quota. Il velivolo è stato intercettato e scortato fino a Budapest da un caccia ungherese, garantendo la sicurezza della manovra di atterraggio. Dopo l'allarme ricevuto a mezz'aria, le procedure di sicurezza sono scattate immediatamente per proteggere passeggeri ed equipaggio. Le autorità locali hanno avviato le ispezioni a bordo per verificare la fondatezza della minaccia. Lo riferisce BBC News.",
