   "id": "zdb793758",
   "sez": "mondo",
   "titolo": "Reddit contesta in tribunale il divieto australiano dei social per i minori di 16 anni",
   "orig": "Reddit and libertarian group challenge Australia’s under-16s social media ban in high court",
   "lead": "Reddit e un gruppo libertario hanno presentato un ricorso all'Alta Corte australiana per contestare il divieto di accesso ai social media per i minori di 16 anni. I ricorrenti sostengono che la legge violi la libertà implicita di comunicazione politica garantita dalla costituzione. La sfida legale, guidata dal Digital Freedom Project, mira a ribaltare il bando che coinvolge numerose piattaforme digitali. Si tratta del primo grande ostacolo giudiziario per la normativa approvata dal governo australiano con l'obiettivo dichiarato di proteggere i giovanissimi dai rischi della rete. Lo riferisce The Guardian.",
