   "sez": "mondo",
   "titolo": "Attacchi con droni colpiscono il sistema elettrico in Sudan",
   "orig": "Drone attacks extend campaign targeting Sudan’s power system",
   "lead": "In Sudan, una serie di attacchi condotti con droni ha colpito nuovamente il sistema elettrico nazionale, aggravando le già critiche forniture di energia nel Paese. Queste azioni si inseriscono in una campagna mirata a destabilizzare le infrastrutture energetiche durante il conflitto civile. Nel frattempo, l'esercito sudanese ha riferito di nuove defezioni tra i ranghi delle forze paramilitari RSF, segnalando possibili cambiamenti negli equilibri di potere interni. La popolazione continua a subire i disagi causati dai blackout prolungati e dall'insicurezza crescente, mentre gli scontri tra le fazioni contrapposte proseguono. Lo riferisce Al Jazeera.",
