   "sez": "prima",
   "titolo": "Incendio a Riga: chiusa un'arteria stradale per rischio crolli",
   "orig": "Traffic near fire in Sarkandaugava to be restricted this week",
   "lead": "A Riga, in Lettonia, un incendio divampato in un edificio disabitato nel quartiere di Sarkandaugava ha causato pesanti restrizioni al traffico che dureranno almeno una settimana. Le autorità municipali hanno chiuso la viabilità nell'area di Tvaika Street per consentire agli ingegneri di valutare la stabilità delle pareti esterne e prevenire crolli pericolosi. Nel frattempo, altre emergenze hanno colpito diverse zone del globo: un vasto rogo è scoppiato in una raffineria a Visakhapatnam, in India, mentre nelle Azzorre sono state spente le luci per proteggere gli uccelli marini durante le loro migrazioni autunnali.",
   "more": [
    "Gli incendi in strutture industriali o edifici abbandonati rappresentano una sfida costante per la sicurezza urbana nelle grandi città. La gestione del traffico durante queste emergenze è fondamentale per garantire l'accesso ai mezzi di soccorso e la protezione dei cittadini da possibili cedimenti strutturali, spesso causati dalle alte temperature che indeboliscono i materiali da costruzione degli edifici vecchi o fatiscenti."
   ],
