   "id": "zd1f64f79",
   "sez": "mondo",
   "titolo": "Papa Leone XIV accoglie con favore l'evacuazione dei civili da Oleshky",
   "orig": "Ukrainian families reunited as Pope welcomes Oleshky humanitarian ceasefire",
   "lead": "Papa Leone XIV ha accolto con favore l'evacuazione di centinaia di civili dalla città ucraina di Oleshky, resa possibile da un raro cessate il fuoco di sei giorni sotto occupazione russa. L'operazione umanitaria è stata mediata con il contributo della First Lady statunitense Melania Trump e si è conclusa senza violazioni, permettendo a molte famiglie di riunirsi. Nonostante il successo della missione, il Cremlino ha escluso per il momento ulteriori operazioni simili, mentre il presidente Zelensky si è detto favorevole a nuove tregue umanitarie lungo altre zone della linea del fronte.",
   "more": [
    "Oleshky è una città strategica situata sulla riva sinistra del fiume Dnipro, nell'oblast di Kherson. Sotto occupazione russa dall'inizio del conflitto, l'area è stata testimone di gravi crisi umanitarie, aggravate dalle inondazioni seguite alla distruzione della diga di Kakhovka. Le tregue temporanee per l'evacuazione dei civili richiedono complessi accordi diplomatici e il monitoraggio di organizzazioni internazionali neutrali."
   ],
