   "titolo": "Olimpiadi della Gioventù Dakar 2026: eliminato il judoka Moussa Ibrahim",
   "orig": "JOJ Dakar 2026 : le judoka centrafricain Moussa Ibrahim éliminé au 2ème tour de repêchage.",
   "lead": "Ai Giochi Olimpici della Gioventù di Dakar 2026, il judoka centrafricano Moussa Ibrahim è stato eliminato al secondo turno di recupero, mancando la possibilità di combattere per la medaglia di bronzo. Nonostante le due vittorie ottenute in quattro incontri, il giovane atleta ha dovuto interrompere il suo percorso nella competizione. Nello stesso evento sportivo, la Francia ha conquistato la medaglia d'oro nel rugby a sette maschile battendo il Sudafrica, mentre la selezione femminile del Madagascar ha sorpreso superando Stati Uniti e Spagna nei match della fase a gironi di lunedì.",
