   "id": "zb3bd2f7e",
   "sez": "ambiente",
   "titolo": "Scienziati avvertono: danni permanenti ai ghiacci se si supera il limite di 1,5 gradi",
   "orig": "Cryosphere faces permanent damage when world overshoots 1.5C, scientists warn",
   "lead": "Un rapporto sostenuto dalle Nazioni Unite avverte che le regioni ghiacciate del pianeta rischiano danni permanenti se la temperatura globale supererà la soglia di 1,5 gradi fissata dagli accordi di Parigi. Gli scienziati sottolineano che anche un superamento temporaneo di tale limite causerebbe perdite irreversibili per ghiacciai e calotte polari, smentendo il mito che un riscaldamento maggiore possa essere gestibile. Il documento raccomanda di riportare il riscaldamento sotto la soglia di 1 grado per preservare la criosfera e prevenire impatti catastrofici sulla stabilità climatica della Terra.",
   "more": [
    "La criosfera comprende tutte le porzioni di superficie terrestre coperte da acqua allo stato solido, come ghiacciai e permafrost. Essa svolge un ruolo cruciale nella regolazione del clima riflettendo la radiazione solare. Lo scioglimento accelerato di queste aree contribuisce all'innalzamento del livello dei mari e altera le correnti oceaniche, con conseguenze dirette sugli ecosistemi e sugli insediamenti costieri."
   ],
