   "id": "z73938251",
   "sez": "ambiente",
   "titolo": "Indonesia, la pioggia aiuta i vigili del fuoco contro gli incendi boschivi",
   "orig": "Firefighters celebrate rain during Indonesia wildfires",
   "lead": "In Indonesia, i vigili del fuoco hanno festeggiato l'arrivo della pioggia, che sta aiutando a domare i vasti incendi boschivi che hanno colpito il Paese. L'Agenzia Nazionale per la Mitigazione dei Disastri sta ora spostando l'attenzione dalla lotta ai roghi alla prevenzione delle inondazioni, tipiche dell'inizio della stagione delle piogge. Nel frattempo, sul fronte energetico, l'azienda Eni ha assegnato contratti per 1,8 miliardi di dollari per lo sviluppo del progetto di gas Cronos al largo di Cipro, che servirà come nuovo hub regionale per rifornire l'Egitto e l'Europa.",
