   "titolo": "EngineeringUK celebra 25 anni e raggiunge 3 milioni di giovani",
   "orig": "EngineeringUK marks 25th anniversary after reaching almost 3M young people",
   "lead": "L'organizzazione no-profit EngineeringUK festeggia il suo venticinquesimo anniversario annunciando di aver raggiunto quasi tre milioni di giovani attraverso le proprie attività e risorse educative. L'ente britannico si occupa di promuovere le carriere tecniche e scientifiche tra le nuove generazioni per colmare il divario di competenze nel settore ingegneristico. Nel mondo dell'intrattenimento, anche il celebre anime Cowboy Bebop celebra i suoi 25 anni: il regista Shinichiro Watanabe ha condiviso riflessioni sul complesso processo creativo dietro il film della serie e sul futuro del franchise. Lo riferisce New Civil Engineer.",
