   "sez": "italia",
   "titolo": "Allarme bomba via email per 271 scuole italiane",
   "orig": "Allarme bomba via mail a 271 scuole",
   "lead": "Un'ondata di allarmi bomba ha colpito oggi 271 scuole in tutta Italia attraverso messaggi di posta elettronica minatori inviati contemporaneamente. Le mail erano firmate da un presunto \"corpo delle guardie della rivoluzione islamica\" e minacciavano esplosioni negli edifici scolastici. La Polizia ha fatto scattare immediatamente le procedure di sicurezza e le bonifiche, interessando in particolare numerosi istituti a Roma. Gli inquirenti della Polizia Postale stanno indagando per risalire agli autori del gesto, che ha causato evacuazioni e forti disagi al regolare svolgimento delle lezioni in diverse città del Paese.",
