   "sez": "cultura",
   "titolo": "Calendario culturale di Chisinau: omaggio al regista Emil Loteanu",
   "orig": "IPN | Cultural Calendar | November 3",
   "lead": "Il 3 novembre a Chisinau si terranno le celebrazioni per il novantesimo anniversario della nascita del celebre regista Emil Loteanu. L'evento prevede l'inaugurazione di una mostra di fotografia documentaria e una tavola rotonda intitolata \"Emil Loteanu – Ambasciatore della cultura nazionale\". L'iniziativa mira a onorare la memoria e l'eredità artistica del grande cineasta, figura di rilievo nel panorama culturale moldavo. Lo riferisce IPN (inglese).",
   "more": [
    "Emil Loteanu è stato uno dei registi più influenti dell'era sovietica in Moldavia, noto a livello internazionale per film come \"I nomadi del cielo\". La sua cinematografia è celebre per lo stile lirico e l'attenzione alle tradizioni popolari e alla musica. Celebrare il suo anniversario sottolinea l'importanza del cinema come strumento di identità nazionale e conservazione della memoria storica nel paese."
   ],
