   "id": "z60e19cec",
   "sez": "dibattito",
   "titolo": "Il paradosso delle pensioni nella legge di bilancio",
   "orig": "Il paradosso delle pensioni nella legge di bilancio",
   "lead": "In Italia si discute delle nuove misure previdenziali contenute nella legge di bilancio. Secondo il governo, l'obiettivo è recuperare risorse economiche intervenendo sugli assegni di molti pensionati; queste somme verrebbero poi utilizzate per finanziare provvedimenti che consentano a un numero limitato di persone di accedere alla pensione in anticipo. La proposta solleva interrogativi sull'equità del sistema, mettendo a confronto il sacrificio richiesto alla maggioranza con il beneficio concesso a pochi. Lo riferisce Il Post.",
   "more": [
    "La legge di bilancio è lo strumento con cui lo Stato stabilisce come reperire e spendere i soldi pubblici per l'anno a venire. Il tema delle pensioni è particolarmente sensibile in Italia per via dell'elevato debito pubblico e della necessità di garantire un ricambio generazionale nel mondo del lavoro senza compromettere la stabilità finanziaria del sistema previdenziale nazionale gestito dall'INPS."
   ],
