   "id": "zc6b9e316",
   "sez": "spazio",
   "titolo": "Successo per il collegamento laser tra il CubeSat ERMIS-3 e la Terra",
   "orig": "CubeSat achieves challenging laser link to ground",
   "lead": "Il nanosatellite ERMIS-3, sviluppato dall'Università Nazionale di Atene, ha stabilito con successo un collegamento ottico con una stazione di terra. Nonostante la complessità dell'operazione, la missione ha validato l'efficacia delle comunicazioni laser per i piccoli satelliti. Il test, supportato dall'Agenzia Spaziale Europea (ESA) e condotto con terminali ottici dell'azienda lituana Astrolight, è avvenuto poche settimane dopo la messa in orbita. Questo risultato rappresenta un passo avanti significativo per le comunicazioni spaziali ad alta velocità.",
   "more": [
    "I CubeSat sono satelliti miniaturizzati che hanno rivoluzionato l'accesso allo spazio riducendo i costi di sviluppo. La comunicazione ottica tramite laser rappresenta l'avanguardia del settore, poiché permette di trasmettere volumi di dati molto superiori rispetto alle tradizionali radiofrequenze, pur richiedendo una precisione estrema nel puntamento verso la stazione a terra per garantire la stabilità del segnale."
   ],
