   "id": "zca95ee1f",
   "sez": "adolescenti",
   "titolo": "Piattaforma PON-POC in tilt: scuole in difficoltà",
   "orig": "PON-POC, piattaforma non funzionante da giorni: scuole in difficoltà per presenze e attività. La segnalazione",
   "lead": "Da quasi dieci giorni la piattaforma INDIRE per la gestione dei progetti formativi PON-POC risulterebbe non funzionante, causando gravi disagi alle istituzioni scolastiche. Le scuole segnalano l'impossibilità di registrare le presenze e gestire le attività quotidiane legate ai finanziamenti europei. La situazione sta creando incertezza sulla continuità dei percorsi didattici e sulla rendicontazione dei progetti in corso, mettendo in difficoltà il personale amministrativo e i docenti impegnati nelle attività. Lo riferisce Orizzonte Scuola.",
   "more": [
    "I Programmi Operativi Nazionali (PON) sono finanziamenti dell'Unione Europea destinati a migliorare il sistema dell'istruzione in Italia. La gestione di questi fondi avviene tramite piattaforme digitali dedicate dove le scuole devono registrare ogni attività per ottenere i rimborsi. Un guasto prolungato di questi sistemi può bloccare i pagamenti e la programmazione didattica supplementare."
   ],
