   "sez": "ambiente",
   "titolo": "Risparmio energetico: il controllo dell'acqua calda supera il solare",
   "orig": "Household hot water savings 'could be bigger than solar'",
   "lead": "Secondo l'organizzazione Powerswitch, il controllo efficiente del riscaldamento dell'acqua domestica potrebbe generare risparmi energetici superiori a quelli ottenibili con l'installazione di pannelli solari. L'utilizzo ottimale dei sistemi di controllo permette alle famiglie di ridurre significativamente i costi in bolletta, a patto che gli impianti siano gestiti correttamente. Questa soluzione viene presentata come un'alternativa più accessibile e immediata per migliorare l'efficienza energetica delle abitazioni senza richiedere investimenti iniziali elevati in infrastrutture rinnovabili. Lo riferisce RNZ.",
   "more": [
    "Il riscaldamento dell'acqua rappresenta una delle voci di spesa più consistenti nei consumi energetici di una casa. L'uso di temporizzatori, l'isolamento dei serbatoi e la regolazione della temperatura possono ridurre gli sprechi. Sebbene il solare sia una fonte pulita, l'efficienza nell'uso dell'energia già disponibile è spesso il modo più rapido ed economico per abbattere le emissioni e i costi domestici."
   ],
