   "titolo": "Bob Dylan torna in Italia con tre concerti",
   "orig": "Bob Dylan in Italia: stasera a Milano, la possibile scaletta del concerto e le date di Roma e Bologna",
   "lead": "Bob Dylan inizia questa sera a Milano, presso l'Unipol Dome, il suo tour italiano intitolato \"Lights of Autumn\". La serie di tre concerti proseguirà il 5 novembre a Roma al Palazzo dello Sport e si concluderà il 7 novembre all'Unipol Arena di Bologna. Il cantautore americano torna nel nostro Paese nell'ambito di una tournée che sta attraversando l'Europa, offrendo ai fan la possibilità di ascoltare i brani del suo vasto repertorio in una scaletta attesissima. Lo riferisce OndaRock.",
   "more": [
    "Bob Dylan, premio Nobel per la Letteratura nel 2016, è considerato uno dei musicisti più influenti del XX e XXI secolo. I suoi tour, noti come \"Never Ending Tour\", si caratterizzano per la continua reinterpretazione dei propri classici, rendendo ogni concerto un evento unico. L'Italia è storicamente una delle tappe più amate dall'artista per l'accoglienza del pubblico e il valore delle location."
   ],
