   "id": "ze79b5e5a",
   "sez": "mondo",
   "titolo": "Funerali al ristorante o al bar: nuove abitudini negli Stati Uniti",
   "orig": "Hosting a Funeral at a Restaurant or Bar",
   "lead": "Negli Stati Uniti si sta diffondendo la tendenza di organizzare cerimonie funebri all'interno di ristoranti e bar, allontanandosi dalle tradizioni classiche e dai luoghi di sepoltura convenzionali. Molte famiglie preferiscono ambienti informali per celebrare la vita dei propri cari, scegliendo locali accoglienti per condividere pasti e ricordi in un'atmosfera meno austera. Questo cambiamento riflette una trasformazione culturale nel modo in cui la società contemporanea affronta il lutto, privilegiando la convivialità rispetto al rito formale. Lo riferisce The New York Times – Cucina.",
   "more": [
    "Le abitudini legate alla morte stanno cambiando radicalmente nei paesi occidentali, con una crescita costante delle cremazioni e una ricerca di riti personalizzati e laici. Questo fenomeno, noto come \"death positivity\" o celebrazione della vita, mira a ridurre lo stigma e la tristezza associati ai funerali tradizionali, trasformandoli in momenti di aggregazione comunitaria e ricordo positivo del defunto."
   ],
