   "id": "ze76c1382",
   "sez": "dibattito",
   "titolo": "Genova: l’autogestione studentesca diventa educazione civica",
   "orig": "Genova, l’autogestione diventa educazione civica: una settimana di film, dibattiti e cura degli spazi. Gli studenti: “Noi non protestiamo solamente, noi collaboriamo per costruire una scuola migliore”",
   "lead": "A Genova, gli studenti di un istituto scolastico hanno trasformato la settimana di autogestione in un progetto formativo di educazione civica. L'iniziativa prevede film, dibattiti e attività di manutenzione degli spazi comuni. Secondo gli studenti, l'obiettivo non è limitarsi alla protesta ma collaborare per costruire una scuola migliore attraverso la cittadinanza attiva. La partecipazione è volontaria: chi sceglie di non aderire può continuare a frequentare le lezioni regolari, garantendo così il rispetto delle diverse esigenze della comunità scolastica. Lo riferisce Orizzonte Scuola.",
   "more": [
    "L'autogestione nelle scuole superiori italiane è una forma di mobilitazione studentesca in cui i ragazzi organizzano autonomamente attività didattiche alternative. Spesso legata a momenti di protesta politica o sociale, in questo caso viene presentata come un'opportunità formativa riconosciuta all'interno del percorso di educazione civica, materia obbligatoria che promuove la responsabilità individuale e collettiva e il rispetto dei beni comuni."
   ],
