   "id": "z3233ab1a",
   "sez": "salute",
   "titolo": "Pediatra a processo in Germania per abusi su oltre 70 bambini",
   "orig": "Doctor in Germany on trial over sex abuse of over 70 children",
   "lead": "Un medico pediatra di 46 anni è sotto processo in Germania con l'accusa di aver abusato sessualmente di oltre 70 bambini. L'uomo deve rispondere di più di 130 capi d'imputazione relativi a fatti avvenuti durante l'esercizio della sua professione. Il caso ha suscitato profonda indignazione pubblica, portando alla luce la gravità e l'estensione delle presunte violenze commesse in ambito sanitario. Le autorità giudiziarie stanno esaminando le prove raccolte per determinare la responsabilità del dottore nei numerosi episodi contestati. Lo riferisce Gulf News.",
   "more": [
    "I procedimenti penali per abusi su minori coinvolgono spesso perizie psichiatriche complesse e lunghe indagini per accertare i fatti. Nel sistema giuridico tedesco, la tutela dell'infanzia è una priorità e casi di tale entità portano spesso a una riflessione nazionale sui protocolli di sicurezza e sorveglianza all'interno delle strutture sanitarie, per prevenire crimini commessi da professionisti che godono della fiducia delle famiglie."
   ],
