   "id": "zae352a2b",
   "sez": "tech",
   "titolo": "Putin impone ai data center privati di riservare il 10% della capacità allo Stato",
   "orig": "Putin orders private data centers in Russia to reserve 10% of their capacity for the state",
   "lead": "Il presidente russo Vladimir Putin ha firmato un decreto che obbliga i proprietari di data center privati a riservare il 10% della loro spazio e della loro capacità operativa per le esigenze dello Stato. La misura mira a sostenere il funzionamento delle risorse informative nazionali e a garantire la resilienza dell'infrastruttura IT russa. La decisione arriva in un periodo in cui le infrastrutture digitali sono diventate bersaglio di crescenti attacchi informatici e fisici, rendendo prioritario per il governo il controllo sulle risorse tecnologiche strategiche. Lo riferisce Meduza.",
   "more": [
    "I data center sono infrastrutture fondamentali per l'economia digitale, poiché ospitano i server necessari per l'archiviazione dei dati. In situazioni di crisi o conflitto, il controllo statale sulla capacità di calcolo diventa strategico per garantire la sicurezza delle reti informatiche e la continuità dei servizi essenziali, permettendo al governo di disporre di spazi pronti per la gestione di emergenze digitali."
   ],
