   "id": "z739ae12c",
   "sez": "economia",
   "titolo": "La Cina consolida il dominio tecnologico globale",
   "orig": "China’s Message to Its Rivals: You Need What We Make",
   "lead": "La Cina sta rendendo sempre più difficile per gli altri Paesi ridurre la dipendenza dalle proprie tecnologie, non limitandosi più solo alle terre rare ma estendendo il controllo a settori come l'energia solare, i droni e la produzione di farmaci. Pechino invia un messaggio chiaro ai rivali internazionali: l'accesso a componenti essenziali per l'industria moderna passa inevitabilmente attraverso le sue aziende. Questa strategia mira a consolidare il ruolo cinese come fornitore indispensabile, complicando gli sforzi di Stati Uniti ed Europa per diversificare le catene di approvvigionamento. Lo riferisce The New York Times.",
   "more": [
    "La Cina ha investito massicciamente per decenni per dominare la produzione di tecnologie chiave per la transizione ecologica e la difesa. Questo controllo le conferisce una leva diplomatica ed economica enorme, poiché gran parte della manifattura globale dipende da standard e componenti cinesi. Il tentativo occidentale di creare filiere alternative richiede investimenti ingenti e tempi molto lunghi per diventare competitivo."
   ],
