   "id": "zc6e9d67e",
   "sez": "musica",
   "titolo": "Deep Purple, tour mondiale rinviato per la salute di Ian Gillan",
   "orig": "Deep Purple, rinviato tutto il tour a causa dei problemi di salute di Ian Gillan",
   "lead": "I Deep Purple hanno annunciato il rinvio dell'intero tour mondiale a causa di seri problemi di salute che hanno colpito il cantante Ian Gillan. Il frontman ha spiegato di aver sperato fino all'ultimo di poter completare le date previste, ma la prosecuzione della tournée avrebbe comportato rischi medici troppo elevati. La band storica ha preferito dare priorità alla guarigione di Gillan, rimandando gli appuntamenti con i fan a data da destinarsi per evitare complicazioni cliniche che avrebbero potuto essere permanenti. Lo riferisce Rolling Stone Italia.",
   "more": [
    "Ian Gillan, voce storica dell'hard rock, è parte dei Deep Purple dalla fine degli anni Sessanta. Rinviare un tour internazionale comporta notevoli sfide logistiche e organizzative, ma la salute degli artisti è ormai prioritaria nell'industria musicale moderna per garantire la longevità delle carriere e la qualità delle performance dal vivo, specialmente per band con decenni di attività alle spalle."
   ],
