   "id": "z8069bff9",
   "sez": "sport",
   "titolo": "AFC Champions League: Al-Nassr vince 6-2 in Uzbekistan senza Ronaldo",
   "orig": "AFC Champions League: Ronaldo rested as Al-Nassr head to Uzbekistan; security fears remain",
   "lead": "Cristiano Ronaldo non ha partecipato alla trasferta dell'Al-Nassr in Uzbekistan per la AFC Champions League Elite. Nonostante l'assenza del fuoriclasse portoghese, tenuto a riposo dall'allenatore Ange Postecoglou, la squadra saudita ha travolto il Pakhtakor con un netto 6-2 a Tashkent. La decisione di escludere Ronaldo è maturata in un clima di persistenti preoccupazioni per la sicurezza nella regione, che avevano già causato il rinvio di precedenti incontri. Per l'Al-Nassr si tratta del secondo successo consecutivo nella massima competizione asiatica per club.",
   "more": [
    "L'AFC Champions League Elite è la competizione calcistica più prestigiosa per i club asiatici. L'arrivo di stelle internazionali nel campionato saudita ha aumentato l'attenzione globale sul torneo. Tuttavia, le tensioni geopolitiche in Medio Oriente continuano a influenzare la logistica delle partite, imponendo spesso spostamenti di sede o misure di sicurezza straordinarie per proteggere atleti e staff."
   ],
