   "id": "zbe2773da",
   "sez": "spazio",
   "titolo": "NASA, l'equipaggio della missione CHAPEA \"torna\" sulla Terra",
   "orig": "NASA’s CHAPEA Crew “Returns” to Earth",
   "lead": "I quattro membri dell'equipaggio CHAPEA della NASA sono \"tornati\" sulla Terra il 31 ottobre 2026, dopo aver completato una missione simulata su Marte durata oltre un anno. Matthew Montgomery, James Spicer, Ross Elder ed Ellen Ellis hanno vissuto in isolamento per testare la salute e le prestazioni umane in condizioni simili a quelle marziane. Questa missione analogica è fondamentale per raccogliere dati preziosi in vista delle future spedizioni umane sul Pianeta Rosso, studiando gli effetti fisici e psicologici della permanenza prolungata in un ambiente ristretto. Lo riferisce Nasa.",
   "more": [
    "Le missioni analoghe come CHAPEA servono alla NASA per anticipare le sfide di un futuro viaggio su Marte. Gli scienziati monitorano la nutrizione, la psicologia e le dinamiche di gruppo dell'equipaggio in un habitat stampato in 3D, per sviluppare protocolli che garantiscano il successo delle missioni reali, riducendo i rischi legati all'isolamento e alla gestione delle risorse."
   ],
