   "id": "z1d1d1ea2",
   "sez": "salute",
   "titolo": "Fiji, problemi di sicurezza ritardano i lavori all'ospedale di Navua",
   "orig": "Navua Hospital upgrade faces delays",
   "lead": "I lavori di ristrutturazione dell'ospedale di Navua hanno subito significativi ritardi a causa di gravi problemi di sicurezza all'interno della struttura. Il Ministro della Salute, il dottor Ratu Atonio Lalabalavu, si è recato presso l'ospedale per spiegare i progressi e le sfide attuali, rispondendo alle sollecitazioni delle autorità locali. Il governo sta lavorando per risolvere le criticità strutturali che impediscono il completamento dell'opera, necessaria per migliorare i servizi sanitari della regione e garantire un ambiente sicuro sia per i pazienti che per il personale medico. Lo riferisce FBC News.",
   "more": [
    "La manutenzione e l'aggiornamento delle infrastrutture sanitarie sono essenziali per garantire standard di cura adeguati. In molte regioni, la vetustà degli edifici e la carenza di fondi possono creare pericoli strutturali, rendendo i lavori di ristrutturazione complessi. Garantire la sicurezza degli ospedali è prioritario per prevenire incidenti durante l'erogazione delle cure e assicurare la continuità assistenziale."
   ],
