   "id": "z5cf68847",
   "sez": "dibattito",
   "titolo": "Calo dei docenti, il Moige lega i tagli alla denatalità e chiede aiuti alle famiglie",
   "orig": "Calo dei docenti, per il Moige è una conseguenza della denatalità. Affinita chiede a Governo di concentrare risorse sulla natalità e sulle famiglie con figli",
   "lead": "In Italia si discute del calo del personale scolastico, tema sollevato dalle proteste di sindacati contro i recenti tagli. Il Moige, Movimento Italiano Genitori, sostiene che la riduzione dei docenti sia una conseguenza naturale della denatalità: con meno bambini nelle classi, il fabbisogno di insegnanti diminuirebbe proporzionalmente. Antonio Affinita, rappresentante del movimento, ha chiesto al Governo di concentrare le risorse sul sostegno alla natalità e alle famiglie con figli, affrontando così la radice del problema demografico. Questa posizione si contrappone a chi vede nei tagli un rischio per la qualità dell'istruzione. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La denatalità in Italia è un fenomeno strutturale che influenza diversi settori, a partire dalla scuola. Il dibattito contrappone chi vede nei tagli un pericolo per l'offerta formativa e chi, come alcune associazioni di genitori, propone di razionalizzare la spesa in base al numero effettivo di alunni, chiedendo però politiche fiscali e sociali più incisive per incentivare la crescita della popolazione e sostenere economicamente i nuclei familiari."
   ],
