   "id": "za7531ae8",
   "sez": "economia",
   "titolo": "Australia, rette record nelle scuole private femminili per il 2027",
   "orig": "‘Like a runaway train’: Private girls’ schools lead 2027 fee hikes",
   "lead": "In Australia, diverse scuole private d'élite per ragazze hanno annunciato aumenti record delle rette per il 2027, con rincari che superano ampiamente il tasso di inflazione. Gli istituti giustificano questa decisione citando l'incremento dei costi del personale e le nuove tasse sui salari introdotte nello stato di Victoria. La notizia ha sollevato preoccupazioni tra le famiglie, che si trovano ad affrontare costi sempre più elevati per l'istruzione non statale, mentre le scuole difendono la necessità di mantenere standard qualitativi elevati nonostante la pressione fiscale crescente. Lo riferisce Sydney Morning Herald.",
   "more": [
    "L'istruzione privata in Australia è un settore rilevante ma costoso. Le variazioni nelle politiche fiscali regionali possono influenzare direttamente i bilanci scolastici. Quando i costi operativi aumentano, queste scuole spesso trasferiscono l'onere sulle rette, alimentando il dibattito nazionale sull'accessibilità economica dell'istruzione di alto livello e sulle crescenti disparità sociali legate alle opportunità educative per le giovani generazioni."
   ],
