   "sez": "spazio",
   "titolo": "NASA, le guide per osservare il cielo di novembre 2026",
   "orig": "What’s Up: November 2026 Skywatching Tips from NASA",
   "lead": "La NASA ha diffuso le previsioni astronomiche per il mese di novembre 2026, segnalando una serie di eventi celesti imperdibili. Tra i fenomeni principali spiccano gli sciami meteorici delle Tauridi e delle Leonidi, oltre alla possibilità di osservare Marte in una posizione vicina a Giove. Il mese sarà caratterizzato anche da una spettacolare Superluna e dal raggiungimento di un traguardo storico per la sonda Voyager 1. Queste indicazioni sono pensate per guidare gli appassionati di astronomia nell'osservazione del cielo notturno, fornendo dettagli tecnici su tempi e visibilità. Lo riferisce Nasa.",
   "more": [
    "Le Superlune si verificano quando la Luna piena coincide con il perigeo, il punto dell'orbita più vicino alla Terra, apparendo più grande e luminosa. Gli sciami meteorici sono invece causati dal passaggio della Terra attraverso i detriti lasciati dalle comete. Questi eventi offrono regolarmente opportunità per studiare la dinamica dei corpi celesti e promuovere la divulgazione scientifica presso il grande pubblico."
   ],
