   "id": "z93b3b12e",
   "sez": "salute",
   "titolo": "Inghilterra, commissione parlamentare boccia il piano contro l'obesità",
   "orig": "Burnham urged to save England&#x2019;s &#x201C;doomed to fail&#x201D; obesity plan",
   "lead": "In Inghilterra, una commissione parlamentare ha lanciato un duro avvertimento sul piano governativo contro l'obesità, definendolo destinato al fallimento. Gli esperti chiedono che il primo ministro assuma personalmente il coordinamento delle azioni sanitarie, integrando diversi dipartimenti per affrontare un'epidemia che grava pesantemente sul sistema sanitario nazionale. Nonostante la promessa di un piano decennale ambizioso, i parlamentari hanno espresso una totale mancanza di fiducia nelle strategie attuali, sollecitando un intervento radicale per risolvere una situazione giudicata critica per la salute pubblica a lungo termine. Lo riferisce The BMJ.",
   "more": [
    "L'obesità è un problema di salute multifattoriale che richiede politiche integrate, dalla regolamentazione alimentare all'istruzione nelle scuole. In Inghilterra, i costi legati alle malattie croniche derivanti dal sovrappeso mettono sotto enorme pressione l'NHS. Un approccio trasversale che coinvolga l'intero governo è spesso ritenuto l'unico modo per ottenere risultati significativi sulla salute della popolazione e sulla sostenibilità del sistema sanitario."
   ],
