   "id": "z94fdc1a9",
   "sez": "ingegneria",
   "titolo": "USA, microrete da 61,5 milioni per l'autonomia energetica di Fort Hood",
   "orig": "Army Corps Awards $61.5M for Fort Hood Microgrid, Built for 14-Day Grid Independence",
   "lead": "L'esercito degli Stati Uniti ha assegnato un contratto da 61,5 milioni di dollari per la costruzione di una seconda microrete elettrica presso la base di Fort Hood, in Texas. L'infrastruttura è progettata per garantire l'indipendenza energetica dell'installazione per un periodo di 14 giorni in caso di interruzione della rete esterna. Questo progetto rientra in un piano più ampio per implementare sistemi energetici resilienti nelle grandi basi militari, assicurando la continuità delle operazioni critiche anche durante emergenze o guasti infrastrutturali prolungati dovuti a cause esterne. Lo riferisce Engineering News-Record.",
   "more": [
    "Le microreti sono sistemi energetici locali capaci di operare autonomamente rispetto alla rete nazionale. In ambito militare, queste infrastrutture sono cruciali per la sicurezza, poiché proteggono le basi da potenziali attacchi informatici, sabotaggi o disastri naturali che potrebbero paralizzare le forniture elettriche tradizionali, garantendo che le comunicazioni e le attività operative vitali non vengano mai interrotte."
   ],
