   "id": "zd9850681",
   "sez": "cultura",
   "titolo": "Trent Reznor e Atticus Ross di nuovo al lavoro con David Fincher",
   "orig": "Trent Reznor and Atticus Ross Are Back at It (Scoring David Fincher Movies)",
   "lead": "Trent Reznor e Atticus Ross collaboreranno nuovamente con il regista David Fincher per comporre la colonna sonora del film \"The Further Mis-Adventures of Cliff Booth\". Questa partnership segna il sesto lavoro congiunto tra il duo di musicisti e il celebre cineasta, un sodalizio artistico che in passato ha prodotto opere di grande successo critico e premi internazionali. La notizia conferma la continuità di uno stile sonoro distintivo che è diventato parte integrante dell'estetica cinematografica di Fincher, consolidando il ruolo di Reznor e Ross come compositori di riferimento a Hollywood. Lo riferisce Pitchfork.",
   "more": [
    "Trent Reznor, leader dei Nine Inch Nails, e Atticus Ross hanno trasformato l'approccio alle colonne sonore utilizzando sonorità elettroniche e industriali. La loro collaborazione con Fincher è iniziata con \"The Social Network\", per il quale hanno vinto l'Oscar. Il sodalizio è celebre per la capacità di creare atmosfere tese e immersive che esaltano la narrazione visiva del regista attraverso un design sonoro innovativo."
   ],
