   "titolo": "Montepremi da 4 milioni di naira per il tennis femminile in Nigeria",
   "orig": "Women’s Tennis: LIS announces ₦4 million prize for inaugural invitational",
   "lead": "L'organizzazione LIS ha annunciato un premio di 4 milioni di naira per il torneo inaugurale invitazionale di tennis femminile in Nigeria. La competizione è stata ideata per migliorare le opportunità di guadagno delle atlete, promuovere l'eccellenza sportiva e incoraggiare gli investimenti del settore privato nello sport femminile. L'iniziativa punta a ridurre il divario di genere nelle competizioni agonistiche del Paese, offrendo maggiore visibilità e supporto economico alle giocatrici professioniste per favorire la loro crescita atletica. Lo riferisce Premium Times.",
   "more": [
    "Il tennis professionistico femminile ha visto negli ultimi anni una crescita significativa degli investimenti e della copertura mediatica globale. In molte nazioni, tuttavia, la disparità di premi e infrastrutture tra i generi rimane una sfida; tornei con montepremi dedicati sono essenziali per permettere alle atlete di sostenere i costi dell'allenamento e competere a livelli internazionali."
   ],
