   "sez": "salute",
   "titolo": "Lo stato di Abia designa un ospedale per l'isolamento da Ebola",
   "orig": "Abia designates specialist hospital as Ebola isolation centre",
   "lead": "Il governo dello Stato di Abia, in Nigeria, ha ufficialmente destinato l'Hospital and Diagnostic Centre di Amachara come centro di isolamento per i casi di Ebola. La struttura servirà come punto di riferimento temporaneo in attesa che vengano completati i lavori per l'Infectious Disease Hospital ad Aba. La decisione rientra nelle misure precauzionali per gestire eventuali emergenze sanitarie legate alla diffusione del virus e garantire una risposta rapida ed efficace sul territorio locale. Lo riferisce The Punch.",
   "more": [
    "Il virus Ebola causa una febbre emorragica grave e spesso letale. La gestione dei focolai richiede protocolli di isolamento rigorosi e strutture specializzate per prevenire il contagio interumano, che avviene tramite il contatto diretto con fluidi corporei infetti. La preparazione delle infrastrutture sanitarie è fondamentale per contenere l'epidemia ed evitare la propagazione in aree popolose."
   ],
