   "sez": "ambiente",
   "titolo": "L'insolito legame tra un asino e un toro incuriosisce gli scienziati",
   "orig": "‘It’s really, really unusual’: tender bond between male donkey and bull baffles scientists",
   "lead": "Un'amicizia interspecie tra l'asino Patroclo e il toro Achille ha attirato l'attenzione della comunità scientifica, fornendo nuove informazioni sulle relazioni sociali e sessuali tra animali. Il legame tra i due, che richiama l'antica amicizia mitologica tra gli eroi greci, è considerato estremamente raro dai ricercatori. Questo caso offre spunti di riflessione sulle dinamiche comportamentali che possono svilupparsi al di fuori delle normali interazioni tra individui della stessa specie, sfidando le conoscenze consolidate in biologia sul comportamento animale. Lo riferisce The Guardian.",
   "more": [
    "L'etologia, la scienza che studia il comportamento animale, ha documentato diversi casi di legami affettivi tra specie differenti, specialmente in contesti di cattività o domesticazione. Questi comportamenti dimostrano che le interazioni sociali degli animali possono essere estremamente complesse e non finalizzate esclusivamente alla riproduzione, rivelando una capacità di socializzazione che trascende le barriere biologiche naturali."
   ],
