   "sez": "cultura",
   "titolo": "Mamdani e Gualtieri cantano \"Bella ciao\" per il Metropolitan Opera",
   "orig": "Mamdani canta Bella ciao con Gualtieri per promuovere opera",
   "lead": "Zohran Mamdani e il sindaco di Roma, Roberto Gualtieri, hanno cantato insieme \"Bella ciao\" in un video promozionale per un'iniziativa culturale tra il Comune di New York e il Metropolitan Opera. Il progetto mette a disposizione 70.000 biglietti gratuiti per assistere a spettacoli d'opera nella metropoli statunitense. Durante lo scambio, Gualtieri ha accennato alla possibilità di lanciare iniziative simili anche nella capitale italiana, rafforzando i legami culturali tra le due città attraverso la musica e la condivisione popolare. Lo riferisce Sky TG24.",
   "more": [
    "\"Bella ciao\" è una celebre canzone popolare italiana, divenuta simbolo universale di resistenza e libertà. La sua esecuzione in contesti istituzionali sottolinea il valore della musica come strumento di diplomazia culturale. Progetti di gratuità per l'accesso alla cultura, come quello del Metropolitan Opera, mirano ad allargare il pubblico dei teatri lirici e a favorire l'inclusione sociale attraverso l'arte."
   ],
