   "sez": "economia",
   "titolo": "Il governo armeno minimizza il rischio di rincari del gas russo",
   "orig": "Ministers Downplay Possible Surge In Russian Gas Price For Armenia",
   "lead": "Alti funzionari del governo di Erevan hanno dichiarato che l'economia armena non subirà gravi danni in caso di un forte aumento del prezzo del gas naturale russo. Nonostante le minacce di Mosca di rincarare le forniture energetiche, i ministri hanno cercato di rassicurare l'opinione pubblica sulla resilienza economica del Paese. La questione dei costi dell'energia rimane tuttavia un tema centrale nei rapporti tra Armenia e Russia, data la forte dipendenza infrastrutturale e l'instabilità geopolitica della regione caucasica. Lo riferisce Azatutyun.",
   "more": [
    "L'Armenia dipende quasi interamente dalle importazioni di gas dalla Russia per il suo fabbisogno energetico. Gazprom gestisce gran parte della rete di distribuzione armena, il che conferisce a Mosca una significativa leva politica. In caso di forti aumenti, lo Stato deve spesso intervenire con sussidi per evitare che i rincari colpiscano eccessivamente i cittadini, mettendo a rischio il bilancio pubblico."
   ],
