   "sez": "salute",
   "titolo": "L'OMS sollecita la conclusione del trattato sulle pandemie",
   "orig": "Recent virus outbreaks show urgent need to complete pandemic treaty, says WHO chief",
   "lead": "Il direttore generale dell'Organizzazione Mondiale della Sanità ha sottolineato l'urgenza di finalizzare un accordo globale sulle pandemie, citando i recenti focolai di Ebola e hantavirus come segnali d'allarme. Secondo il capo dell'OMS, i Paesi devono concludere i negoziati senza ulteriori ritardi per garantire una risposta coordinata alle future emergenze. Il trattato mira a stabilire regole condivise per la gestione dei virus e la distribuzione equa delle risorse mediche, evitando la frammentazione vista durante le crisi passate a livello globale. Lo riferisce Euronews.",
   "more": [
    "Il trattato sulle pandemie è un accordo internazionale in fase di negoziazione tra gli Stati membri dell'OMS per rafforzare la prevenzione e la risposta alle minacce sanitarie. L'obiettivo è superare le disparità nell'accesso ai vaccini e ai farmaci, migliorando al contempo lo scambio di dati scientifici tempestivi tra le nazioni per contenere la diffusione di nuovi agenti patogeni."
   ],
