   "sez": "cultura",
   "titolo": "John Dumelo ricorda l'influenza di Grace Nortey sulla sua carriera",
   "orig": "John Dumelo says Grace Nortey shaped his life from his first film set",
   "lead": "L'attore e politico ghanese John Dumelo ha dichiarato che l'attrice Grace Nortey ha influenzato profondamente la sua vita professionale fin dal suo debutto cinematografico. Dumelo ha lavorato con lei nel 1991, quando era ancora un bambino, sul set del film \"Baby Thief\". L'attore ha reso omaggio all'ispirazione ricevuta dalla collega, sottolineando come quell'esperienza iniziale sia stata determinante per la sua crescita nel mondo dello spettacolo e per il suo successivo impegno pubblico in Ghana. Lo riferisce 3News.",
   "more": [
    "L'industria cinematografica del Ghana ha una lunga storia di talenti che hanno influenzato la cultura popolare dell'Africa occidentale. Figure veterane come Grace Nortey sono considerate pietre miliari per le nuove generazioni di attori, avendo contribuito a definire gli standard recitativi e il successo commerciale del cinema locale dagli anni Novanta in poi, aprendo la strada a carriere internazionali."
   ],
