   "orig": "Queens Of The Stone Age: annunciata una data in Italia nel tour a supporto di “Perfecth”",
   "lead": "I Queens of the Stone Age hanno annunciato una data italiana per il tour a supporto del nuovo album \"Perfecth\", il nono della carriera della band guidata da Josh Homme, pubblicato lo scorso venerdì. Il concerto si terrà il 27 giugno 2027 al Parco San Valentino di Pordenone, come parte della seconda tranche del \"Perfecth World Tour 2027\" in Europa. La band si esibirà anche in altre città europee, tra cui l'Arena di Pola, in Croazia, il 30 giugno 2027.",
