   "id": "z790923ab",
   "sez": "sport",
   "titolo": "Pattinaggio, la kazaka Samodelkina quinta allo Skate Canada Grand Prix",
   "orig": "Kazakhstan’s Samodelkina Finishes Fifth at Skate Canada Grand Prix",
   "lead": "La pattinatrice kazaka Sofya Samodelkina si è classificata quinta al Grand Prix di pattinaggio artistico Skate Canada, con un punteggio totale di 206,89 punti tra programma corto e libero. Samodelkina ha ottenuto 71,84 punti nel programma corto e 135,05 nel libero, piazzandosi tra le prime cinque su dodici concorrenti. La giapponese Mao Shimada ha vinto la competizione. Lo riferisce The Astana Times.",
   "more": [
    "Skate Canada è una delle tappe del circuito Grand Prix ISU di pattinaggio artistico, utile per qualificarsi alla finale di stagione e come banco di prova in vista dei grandi appuntamenti internazionali."
   ],
