   "titolo": "Onu e Francia condannano l'escalation degli attacchi con drone in Sudan",
   "orig": "UN, France condemn escalating drone attacks across Sudan",
   "lead": "Le Nazioni Unite e la Francia hanno condannato l'intensificarsi degli attacchi con drone in diverse zone del Sudan, esprimendo preoccupazione per l'escalation della violenza nel paese. Lo riferisce Dabanga.",
   "more": [
    "Il Sudan è attraversato da un conflitto armato interno tra l'esercito regolare e il gruppo paramilitare delle Forze di supporto rapido, che ha causato una grave crisi umanitaria e milioni di sfollati dal 2023."
   ],
