   "titolo": "Il paese polacco dove 6.000 persone vivono lungo un'unica strada",
   "orig": "Dall’alto sembra un quadro a strisce colorate: il paese dove 6.000 persone vivono su un’unica strada",
   "lead": "Nel distretto di Cracovia, in Polonia, si trova un paese di circa 6.000 abitanti costruito lungo un'unica strada, che visto dall'alto appare come un quadro a strisce colorate. La particolare conformazione urbanistica crea un effetto visivo caratteristico, con colori e sfumature che rendono il luogo una meta insolita per i visitatori. Lo riferisce Turisti per Caso.",
   "more": [
    "In alcune zone rurali dell'Europa centrale esistono villaggi sviluppati lungo un'unica via principale, un modello urbanistico storico legato all'organizzazione agricola del territorio, che oggi attira interesse turistico anche per il particolare impatto visivo osservabile da satellite o drone."
   ],
