   "sez": "salute",
   "titolo": "Un pesticida comune collegato a un rischio di Parkinson 2,5 volte superiore",
   "orig": "Common pesticide linked to 2.5 times the risk of Parkinson’s disease",
   "lead": "Uno studio dell'università della California a Los Angeles (Ucla) ha rilevato che l'esposizione prolungata a un pesticida comune è collegata a un rischio di malattia di Parkinson più di 2,5 volte superiore. I ricercatori hanno anche individuato il meccanismo con cui la sostanza chimica danneggia le cellule cerebrali e hanno identificato un possibile modo per proteggerle. Lo riferisce ScienceDaily.",
   "more": [
    "Il morbo di Parkinson è una malattia neurodegenerativa causata dalla progressiva perdita di cellule nervose che producono dopamina. Diversi studi hanno già collegato l'esposizione prolungata a determinati pesticidi a un aumento del rischio di sviluppare la malattia, soprattutto tra chi lavora in agricoltura."
   ],
