   "titolo": "A Londra serate di boxe femminile per aiutare le sopravvissute a violenze",
   "orig": "The women’s boxing nights helping abuse survivors",
   "lead": "A Londra è nata una nuova serie di incontri di boxe interamente femminili pensati per raccogliere fondi destinati a corsi gratuiti di pugilato. L'iniziativa si rivolge a donne che hanno subito relazioni abusive, offrendo loro uno spazio per ricostruire fiducia in se stesse attraverso l'attività sportiva. L'obiettivo è trasformare un trauma personale in un percorso di rafforzamento fisico e psicologico. Lo riferisce Positive News.",
