   "lead": "Diversi calciatori nigeriani si sono distinti nell'ultimo turno nei campionati europei: Osimhen e Orban hanno segnato in Turchia raggiungendo nove gol in campionato, mentre Onyedika e Moffi hanno brillato in Germania. Arokodare e Awoniyi hanno contribuito con gol importanti per Ajax e Coventry. Anche il marocchino Hakimi ha firmato una tripletta con il PSG, decisivo nella vittoria contro Le Havre. Lo riferiscono Premium Times e Citizen Digital.",
