   "titolo": "La Turchia ha firmato gli Accordi Artemis ma i suoi rover lunari voleranno con la Cina",
   "orig": "Turkey signed US-led Artemis Accords. Its moon rovers will hitch a ride with China",
   "lead": "La Turchia ha firmato gli Accordi Artemis, il quadro di regole statunitense per l'esplorazione lunare, ma il suo primo viaggio verso il polo sud della Luna avverrà probabilmente grazie a un lancio cinese. Un team di oltre 120 studenti e professori della Middle East Technical University di Ankara ha costruito prototipi di due rover con intelligenza artificiale destinati alla missione cinese Chang'e-8, originariamente prevista per il 2028. La Turchia non fa parte della Stazione di ricerca lunare internazionale guidata da Pechino. Lo riferisce South China Morning Post.",
   "more": [
    "Gli Accordi Artemis sono un quadro di principi promosso dagli Stati Uniti per regolare l'esplorazione dello spazio, mentre la Cina sta costruendo un proprio programma lunare alternativo con la missione Chang'e-8, destinata al polo sud della Luna, regione contesa tra le due potenze spaziali."
   ],
