   "titolo": "La compagnia petrolifera statale degli Emirati Arabi Uniti annuncia una partnership con OpenAI",
   "orig": "JAE valstybinė naftos bendrovė paskelbė apie partnerystę su „OpenAI“",
   "lead": "La compagnia petrolifera statale degli Emirati Arabi Uniti, ADNOC, ha annunciato lunedì una partnership con OpenAI, dichiarando che sarà la prima azienda energetica al mondo a utilizzare la piattaforma avanzata di intelligenza artificiale OpenAI Frontier. L'accordo punta a integrare strumenti di intelligenza artificiale avanzata nelle operazioni del settore energetico. Lo riferisce LRT.",
   "more": [
    "OpenAI, l'azienda statunitense dietro ChatGPT, ha stretto negli ultimi anni diverse partnership con governi e grandi aziende internazionali per integrare le proprie tecnologie di intelligenza artificiale in settori strategici come l'energia, puntando a consolidare la propria presenza globale."
   ],
