   "titolo": "Opinione: il sistema sanitario statunitense ha un'economia da riformare",
   "orig": "Opinion: The economics of the U.S. health care system are broken",
   "lead": "In un intervento di opinione, Paul Markovich, presidente e amministratore delegato di Ascendiun, sostiene che l'economia del sistema sanitario degli Stati Uniti sia profondamente disfunzionale. L'articolo analizza le criticità del settore sanitario americano dal punto di vista economico. Lo riferisce STAT.",
   "more": [
    "Il sistema sanitario statunitense si basa in gran parte su assicurazioni private e costi elevati, con spese pro capite tra le più alte al mondo ma risultati non sempre proporzionati. Negli anni si sono susseguiti dibattiti su riforme per contenere i costi e ampliare l'accesso alle cure, senza un consenso politico definitivo sulle soluzioni da adottare."
   ],
