   "sez": "economia",
   "titolo": "Economia australiana verso un rallentamento più marcato con un quinto rialzo dei tassi in vista",
   "orig": "‘Sharper, longer slowdown’ predicted for economy as fifth interest rate hike looms",
   "lead": "Economisti delle principali banche australiane prevedono un rallentamento più profondo e duraturo dell'economia, mentre la Reserve Bank of Australia è attesa martedì con un quinto aumento consecutivo dei tassi d'interesse. La mossa, secondo gli analisti, sarebbe resa necessaria dalla combinazione tra pressioni inflazionistiche persistenti, guerra in Medio Oriente e crollo dei prezzi delle case, che colpirebbe ulteriormente chi ha un mutuo. Lo riferisce The Guardian.",
   "more": [
    "Le banche centrali alzano i tassi d'interesse per contenere l'inflazione, rendendo più costosi mutui e prestiti. Un rialzo prolungato può frenare consumi e investimenti, con il rischio di una recessione se l'economia non si adatta rapidamente ai nuovi costi del credito."
   ],
