   "titolo": "Pechino lancia uno swap da 15 miliardi di dollari per sostenere i mercati cinesi dopo il forte calo",
   "orig": "Beijing launches US$15b asset swap to support China’s markets after sell-off",
   "lead": "La banca centrale cinese ha annunciato lunedì l'avvio di un nuovo meccanismo di swap che convoglierà circa 15 miliardi di dollari verso il mercato azionario interno, dopo il peggior calo mensile in un decennio che ha colpito la fiducia degli investitori. Lo swap, operativo da martedì, permetterà agli investitori istituzionali di scambiare attività poco liquide con strumenti liquidi. Lo riferisce South China Morning Post.",
   "more": [
    "Gli swap di liquidità sono strumenti con cui le banche centrali forniscono fondi temporanei alle istituzioni finanziarie per sostenere i mercati in difficoltà. In Cina, interventi simili sono già stati usati per contenere la volatilità della borsa e rassicurare gli investitori durante periodi di forte instabilità."
   ],
