   "id": "z478699a6",
   "sez": "mondo",
   "titolo": "Il Giappone lancia una nuova agenzia nazionale per la gestione dei disastri",
   "orig": "Japan launches new national agency to deal with disasters",
   "lead": "Il Giappone ha inaugurato lunedì una nuova agenzia nazionale dedicata alla gestione dei disastri, con l'obiettivo di preparare meglio il Paese a eventi come un megaterremoto lungo la costa pacifica o a Tokyo, o un'eruzione del Monte Fuji. Più di 350 dipendenti si occuperanno di prevenzione, risposta alle emergenze e ricostruzione. L'ex premier Ishiba ha sottolineato l'importanza che l'agenzia sia in grado di accumulare e trasmettere conoscenza ed esperienza nella gestione dei disastri. Lo riferiscono CNA, South China Morning Post e The Japan Times.",
   "more": [
    "Il Giappone è uno dei Paesi più esposti al mondo a terremoti, tsunami ed eruzioni vulcaniche per la sua posizione geografica sulla cintura di fuoco del Pacifico. Negli anni il Paese ha sviluppato sistemi avanzati di allerta e prevenzione, ma la frammentazione delle competenze tra diversi enti ha spesso reso difficile una risposta coordinata alle grandi emergenze."
   ],
