   "titolo": "Hong Kong, la Corte finale rigetta l'appello dell'attore Gregory Wong sulla condanna per i disordini del 2019",
   "orig": "Hong Kong top court rejects actor Gregory Wong’s final appeal over 2019 LegCo rioting conviction",
   "lead": "La Corte di appello finale di Hong Kong ha respinto il ricorso dell'attore Gregory Wong contro la condanna per rivolta legata all'assalto al Consiglio legislativo durante le proteste del 2019. Un comitato della corte, composto dai giudici permanenti Roberto Ribeiro e Johnson Lam insieme a un giudice non permanente, ha confermato la sentenza e la pena precedentemente stabilite. Lo riferisce Hong Kong Free Press.",
   "more": [
    "Le proteste del 2019 a Hong Kong, nate da una proposta di legge sull'estradizione, si trasformarono in un movimento di massa contro il governo locale e Pechino, culminato in diversi episodi di violenza, tra cui l'assalto al Parlamento. Da allora centinaia di persone sono state processate e condannate per i disordini."
   ],
