   "orig": "Présidentielle 2027 : Jean-Luc Mélenchon dit annuler sa venue au « 20 heures » de TF1, qu’il accuse d’avoir laissé Edouard Philippe dérouler un « discours dégoûtant » sur l’immigration",
   "lead": "Il leader francese Jean-Luc Mélenchon ha annunciato di annullare la sua presenza al telegiornale delle 20 di TF1, accusando l'emittente di aver lasciato che Édouard Philippe tenesse un discorso che definisce \"disgustoso\" sull'immigrazione. TF1 ha risposto lunedì difendendo la conduzione dell'intervista da parte di Anne-Claire Coudray, precisando che la partecipazione di Mélenchon era già stata annullata dalla fine della settimana precedente e non in reazione all'intervista di Philippe. Lo riferisce Le Monde.",
